Approved prototype of the screen (React, for its layout and texts):
```tsx
import { useState } from 'react';
import {
  Screen,
  Card,
  Grid,
  Stack,
  Row,
  Button,
  Badge,
  Alert,
  KeyBar,
  TextField,
} from '@nexti/ds';

export default function Comprobante({ navigate }: { navigate: (to: string) => void }) {
  const [numero] = useState('00048215');
  const [monto] = useState('$ 12.500,00');
  const [printed, setPrinted] = useState(false);

  const nuevaTransferencia = () => navigate('SCR-TRANSFERENCIA');

  return (
    <Screen
      title="Comprobante"
      code="SCR-COMPROBANTE"
      keys={
        <KeyBar
          actions={[
            { key: 'ENTER', label: 'Nueva transferencia', onPress: nuevaTransferencia, primary: true },
          ]}
        />
      }
    >
      <Stack>
        <Alert tone="success">
          La transferencia se registró correctamente. Conserve este comprobante.
        </Alert>

        <Card
          title="Datos del comprobante"
          actions={<Badge>Registrada</Badge>}
        >
          <Grid columns={2}>
            <div data-field="lblNumero">
              <TextField
                label="Número"
                value={numero}
                onChange={() => {}}
                readOnly
              />
            </div>
            <div data-field="lblMonto">
              <TextField
                label="Monto"
                value={monto}
                onChange={() => {}}
                readOnly
              />
            </div>
          </Grid>
        </Card>

        {printed && (
          <Alert tone="info">
            Se envió el comprobante a imprimir (simulación del prototipo).
          </Alert>
        )}

        <Row>
          <Button variant="primary" shortcut="ENTER" onClick={nuevaTransferencia}>
            Nueva transferencia
          </Button>
          <Button variant="ghost" onClick={() => setPrinted(true)}>
            Imprimir comprobante
          </Button>
        </Row>
      </Stack>
    </Screen>
  );
}
```
